"""Exchange-specific SigningPartner instances for PKI test infrastructure.

Each instance bundles: PEM key, cert usage, and per-device certificate hex data.
"""

from pathlib import Path
from ledgered.devices import DeviceType
from ragger.pki import SigningPartner, CertificatePubKeyUsage

_PKI_DIR = Path(__file__).parent / "pki"

# pylint: disable=line-too-long
TRUSTED_NAME_PARTNER = SigningPartner(
    pem_key_path=_PKI_DIR / "trusted_name.pem",
    cert_pub_key_usage=CertificatePubKeyUsage.TRUSTED_NAME,
    certificates={
        DeviceType.NANOSP: "",
        DeviceType.NANOX:  "",
        DeviceType.STAX:   "",
        DeviceType.FLEX:   "",
        DeviceType.APEX_P: "",
    },
)
# pylint: enable=line-too-long
